using CustomCodeFramework.Core.Pagination;using CustomCodeFramework.Postgres.EntityFramework.Repositories;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Contracts.Taxonomies;using Dhole.Content.Domain.Taxonomies.Entities;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Persistence.Repositories;
public sealed class TaxonomyTermRepository(ServiceDbContext db):EfRepository<TaxonomyTerm,Guid>(db),ITaxonomyTermRepository
{public Task<bool> ExistsBySlugAsync(string siteKey,string kind,string slug,Guid? excludeId=null,CancellationToken ct=default){var s=siteKey.Trim();var k=kind.Trim().ToLowerInvariant();var v=slug.Trim().ToLowerInvariant();return db.TaxonomyTerms.AnyAsync(x=>x.SiteKey==s&&x.Kind==k&&x.Slug==v&&!x.IsDeleted&&(!excludeId.HasValue||x.Id!=excludeId.Value),ct);}public async Task<PagedResult<TaxonomyTermDto>> GetPagedAsync(PageRequest page,string? siteKey=null,string? kind=null,string? search=null,CancellationToken ct=default){var q=db.TaxonomyTerms.AsNoTracking().Where(x=>!x.IsDeleted);if(!string.IsNullOrWhiteSpace(siteKey)){var s=siteKey.Trim();q=q.Where(x=>x.SiteKey==s);}if(!string.IsNullOrWhiteSpace(kind)){var k=kind.Trim().ToLowerInvariant();q=q.Where(x=>x.Kind==k);}if(!string.IsNullOrWhiteSpace(search)){var v=search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(v)||x.Slug.ToLower().Contains(v));}var total=await q.CountAsync(ct);var items=await q.OrderBy(x=>x.SortOrder).ThenBy(x=>x.Name).Skip(page.Skip).Take(page.PageSize).Select(x=>new TaxonomyTermDto(x.Id,x.SiteKey,x.Kind,x.Name,x.Slug,x.Description,x.ParentId,x.SortOrder,x.CreatedAtUtc,x.UpdatedAtUtc)).ToListAsync(ct);return PagedResult<TaxonomyTermDto>.Create(items,page.PageNumber,page.PageSize,total);}}
